import json,csv,pathlib
P=pathlib.Path(__file__).parent
places=[
 dict(id='holy-trinity',name='Church of the Holy Trinity',area='Downtown Toronto',region='Toronto',lat=43.6545,lon=-79.3817,precision='Approximate site',note='The church is documented; the map marker is an approximate orientation point, not an entrance.',access='Check the church’s current visiting arrangements.'),
 dict(id='toronto-sound',name='Toronto Sound Studios',area='Overlea Boulevard, Toronto',region='Toronto',lat=43.706,lon=-79.349,precision='Street area only',note='Rush identifies Overlea Boulevard. The historic building and precise studio position have not yet been verified.',access='Historic studio location; no visitor access is established.'),
 dict(id='massey',name='Massey Hall',area='Downtown Toronto',region='Toronto',lat=43.654,lon=-79.3787,precision='Approximate site',note='The venue is documented; the marker is an approximate orientation point.',access='Check the venue for current events and admission.'),
 dict(id='sharon',name='Sharon Temple',area='Sharon, East Gwillimbury',region='Ontario',lat=44.100,lon=-79.441,precision='Approximate site',note='The temple is documented; the marker is approximate and not a verified entrance.',access='Check the museum’s current opening arrangements.'),
 dict(id='leaskdale',name='Leaskdale Manse',area='Leaskdale, near Uxbridge',region='Ontario',lat=44.205,lon=-79.148,precision='Community area only',note='The manse is documented; the marker represents Leaskdale until its exact coordinates are verified.',access='Check Leaskdale Manse for current tours.'),
 dict(id='thomson',name='Thomson’s Toronto studio',area='Toronto · precise site pending',region='Toronto',lat=None,lon=None,precision='City only · not pinned',note='The AGO confirms a Toronto studio. No building-level pin is assigned from this source.',access='Historic studio; this record does not establish a visitable site.'),
 dict(id='otonabee',name='Otonabee River cabin',area='Near Peterborough, Ontario',region='Ontario',lat=None,lon=None,precision='River area only · not pinned',note='York University identifies the river near Peterborough. No private cabin location is published here.',access='No public access established; do not use as a destination.')]
sources={
 'trinity':dict(title='Cowboy Junkies · The Trinity Session Reissued',url='https://cowboyjunkies.com/trinity-reissued/',publisher='Cowboy Junkies',evidence='The band describes recording at Holy Trinity on 27 November 1987.'),
 'sharon':dict(title='Cowboy Junkies · Sharon, the lost album',url='https://cowboyjunkies.com/new-lost-album-sharon-available-on-vinyl/',publisher='Cowboy Junkies',evidence='Michael Timmins identifies three days at Sharon Temple in April 1989.'),
 'fly':dict(title='Rush · Fly by Night',url='https://www.rush.com/albums/fly-by-night/',publisher='Rush',evidence='Album history identifies Toronto Sound on Overlea Boulevard and the subsequent Caress of Steel sessions. Liner notes confirm recording and mixing.'),
 '2112':dict(title='Rush · 2112',url='https://www.rush.com/albums/2112/',publisher='Rush',evidence='Album history and liner notes identify recording and mixing at Toronto Sound, with Terry Brown.'),
 'stage':dict(title='Rush · All the World’s a Stage',url='https://www.rush.com/albums/all-the-worlds-a-stage/',publisher='Rush',evidence='Liner notes identify live recording at Massey Hall on 11–13 June 1976 and mixing at Toronto Sound.'),
 'wind':dict(title='AGO · Conserving The West Wind',url='https://ago.ca/agoinsider/how-conserve-tom-thomsons-west-wind-1917',publisher='Art Gallery of Ontario',evidence='The AGO distinguishes the outdoor sketch from the large canvas painted in a Toronto studio during winter 1916–17.'),
 'manse':dict(title='Leaskdale Manse · The Manse',url='https://lucymaudmontgomery.ca/?page_id=339',publisher='Leaskdale Manse',evidence='The historic-site page reproduces a plaque naming both novels as written in this house. The plaque’s 1916 date for House of Dreams is not used as a publication date.'),
 'diviners':dict(title='York University · Margaret Laurence',url='https://www.library.yorku.ca/web/archives/whats-new/margaretlaurence/',publisher='Clara Thomas Archives, York University',evidence='The archives biography states that most of The Diviners was written at the Otonabee River cabin during summers 1971–73.')}
works=[]
def add(id,title,creator,medium,place,year,date,stage,source,description,aside):
 works.append(dict(id=id,title=title,creator=creator,medium=medium,place=place,year=year,date=date,stage=stage,source=source,description=description,aside=aside,checked='2026-10-15'))
add('trinity-session','The Trinity Session','Cowboy Junkies','Music','holy-trinity',1987,'27 November 1987','Recorded','trinity','A church becomes a recording room. Cowboy Junkies describe gathering around a single microphone at Holy Trinity and capturing the album in one day.','This connection documents recording, not where every song was written.')
add('west-wind','The West Wind','Tom Thomson','Visual art','thomson',1917,'Winter 1916–17','Painted','wind','A northern landscape took its final, large-scale form in Toronto. The AGO identifies Thomson’s city studio as the place where he painted the canvas over the winter of 1916–17.','The outdoor sketch and the finished canvas belong to different places. This entry concerns the canvas.')
add('anne-island','Anne of the Island','L. M. Montgomery','Literature','leaskdale',1915,'By 1915 · exact writing dates not specified','Written','manse','Anne’s world continued to grow in rural Ontario. The historic-site account names Anne of the Island among the works Montgomery wrote while living at Leaskdale Manse.','The novel’s fictional geography is distinct from its documented writing location.')
add('2112','2112','Rush','Music','toronto-sound',1976,'1976 · recording','Recorded','2112','An ambitious album takes shape on Overlea Boulevard. Rush’s own history identifies Toronto Sound as the recording site, with Terry Brown working alongside the band.','The band’s writing process preceded the studio sessions; this pin represents recording and mixing.')
add('sharon-album','Sharon','Cowboy Junkies','Music','sharon',1989,'April 1989','Recorded','sharon','Three cold spring days in a wooden temple produced an album that remained shelved for decades. Michael Timmins identifies Sharon Temple as the setting for the 1989 sessions.','The date shown is the recording date, not the much later release.')
add('fly-night','Fly by Night','Rush','Music','toronto-sound',1975,'By February 1975 · release month','Recorded','fly','A new chapter in Rush’s sound was recorded and mixed at Toronto Sound Studios. The band’s album history places the studio on Toronto’s Overlea Boulevard.','The listed year is the release year. Exact session dates are not established by the cited page.')
add('all-stage','All the World’s a Stage','Rush','Music','massey',1976,'11–13 June 1976','Recorded live','stage','Three nights at Massey Hall became Rush’s first live album. Its liner notes preserve both the recording venue and the later mixing connection to Toronto Sound.','A live recording is a creation event for the album; it is not the origin of the performed compositions.')
add('anne-house','Anne’s House of Dreams','L. M. Montgomery','Literature','leaskdale',1916,'Leaskdale years, 1911–26 · precise dates pending','Written','manse','A second Anne novel connects back to the same Ontario home. Leaskdale Manse’s historical account explicitly identifies Anne’s House of Dreams as a work written here.','The plaque uses 1916; its meaning requires clarification. The timeline uses that source date provisionally, not as a publication claim.')
add('caress','Caress of Steel','Rush','Music','toronto-sound',1975,'1975 · album year','Recorded','fly','Toronto Sound connects several stages of Rush’s early discography. The band’s Fly by Night history also names Caress of Steel among the albums recorded at the studio.','This entry relies on the band’s retrospective studio history; exact session dates remain unspecified.')
add('diviners','The Diviners','Margaret Laurence','Literature','otonabee',1972,'Summers 1971–73','Mostly written','diviners','A cabin beside the Otonabee River became a working retreat. York University’s archives identify it as the place where Laurence wrote most of The Diviners over three summers.','The evidence supports a substantial part of the writing, not the entire novel or its first idea.')
data=dict(version='0.1.0',checked='2026-10-15',places=places,sources=sources,works=works)
P.joinpath('catalogue.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
with P.joinpath('catalogue.csv').open('w',newline='') as f:
 w=csv.writer(f);w.writerow(['id','work','creator','medium','creation_stage','date_label','place','location_precision','source_url','checked','notes'])
 for x in works:
  p=next(p for p in places if p['id']==x['place']);w.writerow([x['id'],x['title'],x['creator'],x['medium'],x['stage'],x['date'],p['name'],p['precision'],sources[x['source']]['url'],x['checked'],x['aside']])
